const input = $input.first().json;
const body = input.body || input;
const curriculum = body.curriculum || {};
const course = curriculum.course || body.course || {};
const modules = curriculum.modules || body.modules || [];
const generatedLessons = body.generated_lessons || [];
const generatedQuizzes = body.generated_quizzes || [];

// Validation checks
const errors = [];

if (!course.title) errors.push('Titre du cours manquant');
if (!modules.length) errors.push('Aucun module trouvé');

for (const mod of modules) {
  if (!(mod.lessons || []).length) {
    errors.push(`Module ${mod.module_number}: aucune leçon`);
  }
  for (const lesson of (mod.lessons || [])) {
    if (!lesson.content && !lesson.content_html) {
      // May need content from generated_lessons
    }
  }
}

const totalLessons = modules.reduce((sum, m) => sum + (m.lessons || []).length, 0);
const totalHours = modules.reduce((sum, m) => sum + (m.duration_minutes || 60), 0) / 60;

return [{
  json: {
    course,
    modules,
    generated_lessons: generatedLessons,
    generated_quizzes: generatedQuizzes,
    validation: {
      errors,
      is_valid: errors.length === 0,
      total_modules: modules.length,
      total_lessons: totalLessons,
      estimated_hours: Math.round(totalHours * 10) / 10
    }
  }
}];

const data = $input.first().json;
const course = data.course;
const modules = data.modules;
const now = new Date().toISOString();

// Build the complete Formation document matching src/types/index.ts
const slug = (course.slug || course.title || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 80);

// Build modules with lessons in the exact Formation.modules format
const formationModules = modules.map((mod, mi) => {
  const lessons = (mod.lessons || []).map((lesson, li) => ({
    id: lesson.id || crypto.randomUUID(),
    title: lesson.title,
    type: lesson.type || 'text',
    duration: lesson.duration || `${lesson.duration_minutes || 10} min`,
    content: lesson.content || lesson.content_html || '',
    videoUrl: lesson.videoUrl || '',
    resources: (lesson.resources || []).map(r => ({
      id: r.id || crypto.randomUUID(),
      title: r.title || '',
      type: r.type || 'link',
      url: r.url || '',
      size: r.size || ''
    })),
    order: lesson.order || li + 1,
    isFree: lesson.isFree || (mi === 0 && li === 0)
  }));

  return {
    id: mod.id || crypto.randomUUID(),
    title: mod.title,
    order: mod.module_number || mi + 1,
    lessons
  };
});

const formation = {
  title: course.title,
  slug,
  description: course.short_description || course.description?.substring(0, 200) || '',
  longDescription: course.description || '',
  coverImage: course.coverImage || '',
  level: course.level || 'debutant',
  price: 0,
  promoPrice: 0,
  duration: `${data.validation.estimated_hours}h`,
  modules: formationModules,
  category: course.category || 'Marketing Digital',
  tags: course.tags || [],
  students: 0,
  rating: 0,
  status: 'draft',
  featured: false,
  certificateEnabled: course.certification !== false,
  metaTitle: course.title,
  metaDescription: course.short_description || '',
  focusKeyword: (course.tags || [])[0] || '',
  ogTitle: course.title,
  ogDescription: course.short_description || '',
  ogImage: '',
  noIndex: false,
  createdAt: now
};

return [{ json: { formation, slug } }];

const f = $json.formation;

// Serialize to Firestore REST API format
function toFirestoreValue(value) {
  if (value === null || value === undefined) return { nullValue: null };
  if (typeof value === 'string') return { stringValue: value };
  if (typeof value === 'number') {
    if (Number.isInteger(value)) return { integerValue: String(value) };
    return { doubleValue: value };
  }
  if (typeof value === 'boolean') return { booleanValue: value };
  if (Array.isArray(value)) {
    return { arrayValue: { values: value.map(toFirestoreValue) } };
  }
  if (typeof value === 'object') {
    const fields = {};
    for (const [k, v] of Object.entries(value)) {
      fields[k] = toFirestoreValue(v);
    }
    return { mapValue: { fields } };
  }
  return { stringValue: String(value) };
}

const fields = {};
for (const [key, value] of Object.entries(f)) {
  fields[key] = toFirestoreValue(value);
}

return [{ json: { firestoreDoc: { fields }, slug: $json.slug } }];

const firestoreResponse = $input.first().json;
const docName = firestoreResponse.name || '';
const docId = docName.split('/').pop() || '';

return [{
  json: {
    success: !!docId,
    document_id: docId,
    document_path: docName,
    slug: $('Serialize — Format Firestore').first().json.slug
  }
}];
